import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.B9qR_F1m.js";const u=JSON.parse('{"title":"Versions, outdated and upgrade","description":"","frontmatter":{},"headers":[],"relativePath":"upgrades.md","filePath":"upgrades.md"}'),s={name:"upgrades.md"};function i(d,e,n,c,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="versions-outdated-and-upgrade" tabindex="-1">Versions, <code>outdated</code> and <code>upgrade</code> <a class="header-anchor" href="#versions-outdated-and-upgrade" aria-label="Permalink to &quot;Versions, `outdated` and `upgrade`&quot;">​</a></h1><h2 id="detected-versions" tabindex="-1">Detected versions <a class="header-anchor" href="#detected-versions" aria-label="Permalink to &quot;Detected versions&quot;">​</a></h2><p>After installing a tool, ripeat runs its recipe&#39;s <code>version</code> command (or <code>check</code>) and stores the first dotted number it prints (<code>2.43.0</code>). Pre-existing tools are detected the same way. <code>ripeat list</code> shows it.</p><h2 id="is-there-a-newer-ripeat-ripeat-version-check" tabindex="-1">Is there a newer ripeat? <code>ripeat version --check</code> <a class="header-anchor" href="#is-there-a-newer-ripeat-ripeat-version-check" aria-label="Permalink to &quot;Is there a newer ripeat? `ripeat version --check`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # just the version</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # also asks GitHub whether a newer release is out</span></span></code></pre></div><p>It reads the latest release of the public releases repository and compares numbers (<code>0.10.0</code> is newer than <code>0.9.0</code>). If there is a newer one it prints the upgrade command that fits how ripeat was installed: <code>brew update &amp;&amp; brew upgrade ripeat/tap/ripeat</code> for Homebrew, <code>scoop update ripeat</code> for Scoop, or the releases page for a download. It never downloads or replaces anything itself. A build made from source (<code>0.1.0-dev</code>) has nothing to compare. Built-in recipes are part of the release, so upgrading ripeat is also how they are updated.</p><h2 id="ripeat-outdated" tabindex="-1"><code>ripeat outdated</code> <a class="header-anchor" href="#ripeat-outdated" aria-label="Permalink to &quot;`ripeat outdated`&quot;">​</a></h2><p>For each tool ripeat installed, asks its package manager whether a newer version exists, and prints <code>installed -&gt; newer</code> or <code>(up to date)</code>.</p><ul><li>Works for <code>apt</code>, <code>dnf</code>, <code>pacman</code>, <code>brew</code> and <code>brew_cask</code>. Other methods print &quot;cannot check yet&quot;.</li><li>It reads the package manager&#39;s <strong>current</strong> index and does not refresh it. Refresh first (for example <code>sudo apt-get update</code>) to see the newest versions.</li><li>Pre-existing tools are listed as not managed by ripeat; they are never upgraded.</li><li>Versions shown are the package manager&#39;s (<code>1:2.43.0-1ubuntu7.4</code>), which is also what <code>ripeat.lock</code> records.</li></ul><h2 id="ripeat-upgrade-tool" tabindex="-1"><code>ripeat upgrade [tool ...]</code> <a class="header-anchor" href="#ripeat-upgrade-tool" aria-label="Permalink to &quot;`ripeat upgrade [tool ...]`&quot;">​</a></h2><p>Upgrades the outdated tools (all of them, or the ones named).</p><ul><li>Shows the list, then asks <code>Upgrade N tools as shown above? [y/N]</code> (<code>--yes</code> answers for you; with no terminal it refuses without it).</li><li>Asks for admin rights once up front (<a href="./privileges">Admin rights</a>).</li><li>Recorded as one run in the journal, one step per tool.</li><li><code>--dry-run</code> shows the commands.</li><li><strong>Upgrades cannot be rolled back</strong>: ripeat does not keep the old version. <code>ripeat rollback</code> on an upgrade run says so and leaves the tools upgraded; the next <code>rollback</code> then reaches the run underneath.</li><li>If one tool fails, earlier upgrades in that run stay in place.</li><li><code>pacman</code> upgrades a single package without a full system upgrade, which Arch discourages; prefer <code>pacman -Syu</code> yourself on Arch.</li></ul>',12)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
